contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // msg.sender for calls to c will be this contract
    // amount must be provided and used to call play
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount, "insufficient balance to forward");
        // record observables before
        address bankBefore = c.bank(); if (__ESBMC_reverted()) return;
        uint potBefore = c.pot(); if (__ESBMC_reverted()) return;
        uint cBalanceBefore = address(c).balance;
        uint myBalanceBefore = address(this).balance;

        bool reverted;
        // make the call that may change state; send Ether amount
        c.play{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // read observables after
        address bankAfter = c.bank(); if (__ESBMC_reverted()) return;
        uint potAfter = c.pot(); if (__ESBMC_reverted()) return;
        uint cBalanceAfter = address(c).balance;
        uint myBalanceAfter = address(this).balance;

        // General rule:
        // - bank address never changes
        // - if the call reverted then none of pot or balances changed
        // - if call did not revert and amount == TICKET_AMOUNT, then either:
        //     * a payout occurred: potAfter == 0, cBalanceAfter == cBalanceBefore - c.FEE_AMOUNT() - (potBefore) + (amount) ???
        // However we cannot call constants directly; express balance relation using observed shifts:
        // Simpler invariant to prove: when not reverted and amount == TICKET_AMOUNT,
        //    (bank unchanged) && (cBalanceAfter == cBalanceBefore + (potAfter - potBefore))
        // This states that changes in c.eth balance equal changes in pot (i.e., any Ether moved out to players/bank is reflected as pot change).

        // Note: use the contract's known constants via numeric literals is allowed in asserts; to stay general we avoid relying on them.
        assert(
            // bank never changes
            bankBefore == bankAfter
            && (
                // if reverted: nothing changed
                (reverted && potBefore == potAfter && cBalanceBefore == cBalanceAfter && myBalanceBefore == myBalanceAfter)
                ||
                // else: when call succeeded, change in c balance equals change in pot
                (!reverted && cBalanceAfter == cBalanceBefore + (potAfter - potBefore))
            )
        );
    }

    // allow receiving refunds/transfers when payout happens
    receive() external payable {}
}

